                        map.len = (if (comptime @typeInfo(@TypeOf(default.len)) == .@"enum") cp_cast_int(u32, @intFromEnum(default.len)) else cp_cast_int(u32, default.len));
                        slice = map.slice();
                    } else {
                        _ = @compileError(std.fmt.comptimePrint("Cannot set length of {s}", .{ @typeName(Array) }));
                    }
                }
            } else {
                if (comptime std.meta.trait.isSlice(Array)) {
                    slice = try allocator.alloc(Of(Array), default.len);
                } else {
                    if (comptime @hasField(map, "ptr")) {
                        slice = try allocator.alloc(Of(Array), default.len);
                        map = .{ .ptr = slice.ptr, .len = (if (comptime @typeInfo(@TypeOf(default.len)) == .@"enum") cp_cast_int(u32, @intFromEnum(default.len)) else cp_cast_int(u32, default.len)), .cap = (if (comptime @typeInfo(@TypeOf(default.len)) == .@"enum") cp_cast_int(u32, @intFromEnum(default.len)) else cp_cast_int(u32, default.len)) };
                    }
                }
            }
            const in_bytes = std.mem.sliceAsBytes(default);
            var out_bytes = std.mem.sliceAsBytes(slice);
            _ = &out_bytes;
            _ = @memcpy(out_bytes[0..in_bytes.len], in_bytes);
            if (bun.trait.isSlice(Array)) {
                return slice;
            }
            return map;
        }
}

pub fn needsAllocator(comptime Fn: anytype) bool {
        return (std.meta.fields(std.meta.ArgsTuple(@TypeOf(Fn))).len > 2);
}
